def run(state, rules, max_steps=1000, parallel=False):
    for rule in rules:
        for key in ("name", "salience", "condition", "action"):
            if key not in rule:
                raise ValueError(f"rule is missing {key!r}")
    ordered = sorted(rules, key=lambda r: (-r["salience"], r["name"]))
    fired = {rule["name"]: 0 for rule in rules}
    current = dict(state)
    steps = 0
    while steps < max_steps:
        if parallel:
            matches = [r for r in ordered if r["condition"](current)]
            if not matches:
                break
            steps += 1
            snapshot = dict(current)
            updates = {}
            for rule in matches:
                fired[rule["name"]] += 1
                updates.update(rule["action"](snapshot))
            if updates == {k: current[k] for k in updates if k in current} and \
                    all(k in current for k in updates):
                current.update(updates)
                break
            current.update(updates)
        else:
            for rule in ordered:
                if rule["condition"](current):
                    steps += 1
                    fired[rule["name"]] += 1
                    current.update(rule["action"](dict(current)))
                    break
            else:
                break
    return {"state": current, "fired": fired, "steps": steps,
            "quiescent": steps < max_steps}
